# Windows VM smoke test for binaries generated by `yerux build --native --target windows` (PE writer: .pdata/.xdata
# unwind info and ASLR). Runs INSIDE the VM (~/vm-windows, Windows PowerShell 5.1); the host driver
# tests/windows_vm_smoke.sh builds the programs, serves them from ~/vm-windows/serve/smoke/ and submits this file as a
# job (host.py hands it to agent.ps1, which posts the output back to ~/vm-windows/results/<id>.txt).
#
# The driver prepends the job variables:
#   $Base   = 'http://10.0.2.2:8000/files/smoke'     where the host serves the files
#   $Progs  = @('name', ...)                         <name>.exe with expected stdout <name>.out (exit code 0)
#   $Spin   = 'spin'                                 <name>.exe: a program that runs ~1 s (image base is read while it runs)
#
# Checks (each prints PASS/FAIL, the last line is `windows_vm_smoke: N failure(s)`):
#   1. every program runs and prints exactly the expected stdout, exit code 0
#   2. the PE header has DYNAMIC_BASE, HIGH_ENTROPY_VA and NX_COMPAT
#   3. ASLR: the spinning program is started 6 times; the loader must have moved the image away from its preferred
#      base 0x140000000 (the bias is chosen once per boot, so the base is stable within one boot)
#   4. unwind info: the image is mapped with LoadLibraryEx and, for every function, RtlLookupFunctionEntry finds the
#      RUNTIME_FUNCTION and RtlVirtualUnwind, started at the end of the prologue on a synthetic frame, returns the
#      caller's rip/rsp/rbp that were planted in it
$ErrorActionPreference = 'Stop'
$fails = 0
function Ok($m)   { "PASS: $m" }
function Bad($m)  { $script:fails++; "FAIL: $m" }
$dir = 'C:\yerux-smoke'
Remove-Item $dir -Recurse -Force -ErrorAction SilentlyContinue
New-Item -ItemType Directory $dir | Out-Null
$wc = New-Object Net.WebClient
foreach ($n in ($Progs + $Spin)) { $wc.DownloadFile("$Base/$n.exe", "$dir\$n.exe") }
foreach ($n in $Progs) { $wc.DownloadFile("$Base/$n.out", "$dir\$n.out") }

# 1. behaviour
foreach ($n in $Progs) {
  $out = (& "$dir\$n.exe" | Out-String)
  $code = $LASTEXITCODE
  $want = [IO.File]::ReadAllText("$dir\$n.out")
  $a = ($out -replace "`r", '').TrimEnd("`n"); $b = ($want -replace "`r", '').TrimEnd("`n")
  if ($code -eq 0 -and $a -ceq $b) { Ok "$n runs" } else { Bad "${n}: exit $code, output differs" }
}

# 2. PE header flags
function PeInfo($path) {
  $b = [IO.File]::ReadAllBytes($path)
  $pe = [BitConverter]::ToInt32($b, 0x3C)
  $opt = $pe + 24
  $nsec = [BitConverter]::ToUInt16($b, $pe + 6)
  $soh = [BitConverter]::ToUInt16($b, $pe + 20)
  $secs = @()
  for ($i = 0; $i -lt $nsec; $i++) {
    $o = $opt + $soh + 40 * $i
    $secs += [pscustomobject]@{ Name = ([Text.Encoding]::ASCII.GetString($b, $o, 8)).TrimEnd([char]0); Rva = [BitConverter]::ToUInt32($b, $o + 12); Size = [BitConverter]::ToUInt32($b, $o + 8); Ptr = [BitConverter]::ToUInt32($b, $o + 20) }
  }
  [pscustomobject]@{ Bytes = $b; DllChar = [BitConverter]::ToUInt16($b, $opt + 70); Dd = $opt + 112; Secs = $secs }
}
function RvaOff($info, $rva) {
  foreach ($s in $info.Secs) { if ($rva -ge $s.Rva -and $rva -lt $s.Rva + $s.Size) { return [int]($s.Ptr + $rva - $s.Rva) } }
  throw "RVA $rva in no section"
}
foreach ($n in ($Progs + $Spin)) {
  $i = PeInfo "$dir\$n.exe"
  $need = 0x40 -bor 0x20 -bor 0x100
  if (($i.DllChar -band $need) -eq $need) { Ok "$n DllCharacteristics $('{0:X}' -f $i.DllChar)" } else { Bad "$n DllCharacteristics $('{0:X}' -f $i.DllChar) lacks ASLR flags" }
}

# 3. ASLR: the image base differs between runs
$bases = @()
for ($k = 0; $k -lt 6; $k++) {
  $p = Start-Process -FilePath "$dir\$Spin.exe" -PassThru -WindowStyle Hidden -RedirectStandardOutput "$dir\spin.txt"
  $base = $null
  for ($t = 0; $t -lt 50 -and -not $base; $t++) {
    try { $p.Refresh(); $base = $p.MainModule.BaseAddress.ToInt64() } catch { Start-Sleep -Milliseconds 20 }
  }
  $bases += $base
  $p.WaitForExit()
}
$distinct = ($bases | Sort-Object -Unique).Count
"image bases: " + (($bases | ForEach-Object { '{0:X}' -f $_ }) -join ' ')
# Windows picks the ASLR bias once per boot, so the same image gets the same base in every run of one boot: what a
# position-independent image must show is that the loader MOVED it (it asked for 0x140000000) and that it still ran.
if ($bases | Where-Object { $_ -eq 0x140000000 }) { Bad "ASLR: loaded at the preferred base 0x140000000 (not relocated)" } else { Ok "ASLR: image relocated away from the preferred base ($distinct distinct base(s) in 6 runs of this boot)" }
if ($bases | Where-Object { -not $_ }) { Bad "ASLR: could not read the image base" } else { Ok "ASLR: image base read from the running process" }

# 4. unwind information, checked by the OS routines
Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
public static class Unw {
  [DllImport("kernel32.dll", SetLastError=true, CharSet=CharSet.Unicode)] public static extern IntPtr LoadLibraryEx(string f, IntPtr h, uint flags);
  [DllImport("kernel32.dll")] public static extern IntPtr RtlLookupFunctionEntry(ulong pc, out ulong imageBase, IntPtr history);
  [DllImport("kernel32.dll")] public static extern IntPtr RtlVirtualUnwind(uint type, ulong imageBase, ulong pc, IntPtr fn, IntPtr ctx, out IntPtr handlerData, out ulong frame, IntPtr ptrs);
}
'@
foreach ($n in ($Progs + $Spin)) {
  $i = PeInfo "$dir\$n.exe"
  $b = $i.Bytes
  $h = [Unw]::LoadLibraryEx("$dir\$n.exe", [IntPtr]::Zero, 1)   # DONT_RESOLVE_DLL_REFERENCES
  if ($h -eq [IntPtr]::Zero) { Bad "${n}: LoadLibraryEx failed ($([Runtime.InteropServices.Marshal]::GetLastWin32Error()))"; continue }
  $imageBase = [uint64]$h.ToInt64()
  $pdRva = [BitConverter]::ToUInt32($b, $i.Dd + 8 * 3); $pdSize = [BitConverter]::ToUInt32($b, $i.Dd + 8 * 3 + 4)
  $pdOff = RvaOff $i $pdRva
  $nfun = $pdSize / 12
  $bad = 0; $framed = 0
  $stack = [Runtime.InteropServices.Marshal]::AllocHGlobal(8192)
  $ctx = [Runtime.InteropServices.Marshal]::AllocHGlobal(1232 + 16)
  $ctxA = [IntPtr]([int64]($ctx.ToInt64() + 15) -band -16)
  for ($f = 0; $f -lt $nfun; $f++) {
    $begin = [BitConverter]::ToUInt32($b, $pdOff + 12 * $f); $unw = [BitConverter]::ToUInt32($b, $pdOff + 12 * $f + 8)
    $u = RvaOff $i $unw
    $prolog = $b[$u + 1]; $ncodes = $b[$u + 2]
    $baseNew = [uint64]0
    $fe = [Unw]::RtlLookupFunctionEntry($imageBase + $begin + $prolog, [ref]$baseNew, [IntPtr]::Zero)
    if ($fe -eq [IntPtr]::Zero -or $baseNew -ne $imageBase) { $bad++; "  function $f at RVA $('{0:X}' -f $begin): no RUNTIME_FUNCTION"; continue }
    if ($ncodes -eq 0) { continue }
    $framed++
    # frame size from the first unwind code (ALLOC_SMALL / ALLOC_LARGE), 0 when the first code is SET_FPREG
    $op = $b[$u + 5] -band 15; $info = $b[$u + 5] -shr 4; $frame = 0
    if ($op -eq 2) { $frame = 8 * $info + 8 }
    elseif ($op -eq 1 -and $info -eq 0) { $frame = 8 * [BitConverter]::ToUInt16($b, $u + 6) }
    elseif ($op -eq 1) { $frame = [BitConverter]::ToUInt32($b, $u + 6) }
    # synthetic frame: [rbp] = caller rbp, [rbp+8] = return address; rsp = rbp - frame
    $rbp = [uint64]($stack.ToInt64() + 4096)
    [Runtime.InteropServices.Marshal]::WriteInt64([IntPtr][int64]$rbp, 0x1111)
    [Runtime.InteropServices.Marshal]::WriteInt64([IntPtr][int64]($rbp + 8), 0x2222)
    for ($z = 0; $z -lt 1232; $z += 8) { [Runtime.InteropServices.Marshal]::WriteInt64($ctxA, $z, 0) }
    [Runtime.InteropServices.Marshal]::WriteInt32($ctxA, 0x30, 0x100003)       # CONTEXT_CONTROL | CONTEXT_INTEGER
    [Runtime.InteropServices.Marshal]::WriteInt64($ctxA, 0x98, [int64]($rbp - $frame))   # Rsp
    [Runtime.InteropServices.Marshal]::WriteInt64($ctxA, 0xA0, [int64]$rbp)              # Rbp
    [Runtime.InteropServices.Marshal]::WriteInt64($ctxA, 0xF8, [int64]($imageBase + $begin + $prolog)) # Rip
    $hd = [IntPtr]::Zero; $ef = [uint64]0
    [void][Unw]::RtlVirtualUnwind(0, $imageBase, $imageBase + $begin + $prolog, $fe, $ctxA, [ref]$hd, [ref]$ef, [IntPtr]::Zero)
    $rip = [Runtime.InteropServices.Marshal]::ReadInt64($ctxA, 0xF8); $rsp = [Runtime.InteropServices.Marshal]::ReadInt64($ctxA, 0x98); $rb = [Runtime.InteropServices.Marshal]::ReadInt64($ctxA, 0xA0)
    if ($rip -ne 0x2222 -or $rsp -ne [int64]($rbp + 16) -or $rb -ne 0x1111) {
      $bad++; "  function $f (frame $frame): unwound to rip=$('{0:X}' -f $rip) rsp-delta=$($rsp - [int64]$rbp) rbp=$('{0:X}' -f $rb)"
    }
  }
  if ($bad -eq 0) { Ok "$n unwind info: $nfun functions ($framed framed) unwind to the planted caller" } else { Bad "$n unwind info: $bad of $nfun functions wrong" }
}
"windows_vm_smoke: $fails failure(s)"
exit $fails
